function values = simuverity_formal90_public_nominal_inputs( ...
        benchmarkTaskId, publicNames)
%simuverity_formal90_public_nominal_inputs Staged provider.
% Public nominal provider.  Eight project-backed current outputs are loaded
% from a same-directory evaluator-owned file path-bound MAT bundle.  XFLUID-08 is
% supplied by the separately authorized current nominal policy.  All other tasks
% delegate to the immutable, same-directory current provider.

benchmarkTaskId = string(benchmarkTaskId);
publicNames = unique(string(publicNames(:)), "stable");
publicNames(publicNames == "") = [];

runtimeRoot = string(fileparts(mfilename("fullpath")));
baseProviderPath = fullfile(runtimeRoot, ...
    "simuverity_xfluid04_public_nominal_inputs.m");
bundlePath = fullfile(runtimeRoot, ...
    "unified_formal90_remaining58_public_nominal_fixture_bundle.mat");
localRequirePresence(baseProviderPath, ...
    "present", ...
    "NominalProvider");

bundleTaskIds = [ ...
    "F90-XBATT-06"; "F90-XBATT-09"; "F90-XCOMM-02"; ...
    "F90-XMECH-03"; "F90-XMED-08"; "F90-XROBO-04"; ...
    "F90-XROBO-07"; "F90-XROBO-09"];
if benchmarkTaskId == "F90-XFLUID-08"
    localRequireNames(publicNames, ["flight_fuel_command"; ...
        "initial_fuel_volume_m3"]);
    time = [0.0; 3000.0];
    command = repmat([0.0, 0.0, 120.0, 120.0, 120.0, 120.0], 2, 1);
    values = struct( ...
        "flight_fuel_command", timeseries(command, time), ...
        "initial_fuel_volume_m3", [10.0, 10.0, 5.0]);
elseif any(benchmarkTaskId == bundleTaskIds)
    localRequirePresence(bundlePath, ...
        "present", ...
        "FixtureBundle");
    payload = load(bundlePath, "fixtureBundle");
    bundle = payload.fixtureBundle;
    assert(string(bundle.schema) == ...
        "simuverity.formal90-remaining58-public-nominal-fixture-bundle.v1" && ...
        double(bundle.task_count) == 8, ...
        "SimuVerity:CandidateClosure:Formal90BundleContract", ...
        "The evaluator-owned current fixture bundle has the wrong schema or count.");
    rowIds = string({bundle.tasks.benchmark_task_id}).';
    rowIndex = find(rowIds == benchmarkTaskId);
    assert(isscalar(rowIndex), ...
        "SimuVerity:CandidateClosure:Formal90BundleTask", ...
        "The evaluator-owned current fixture bundle lacks one exact task row.");
    expectedNames = string(bundle.tasks(rowIndex).public_input_names(:));
    localRequireNames(publicNames, expectedNames);
    values = bundle.tasks(rowIndex).values;
    assert(isstruct(values) && isscalar(values) && ...
        isequal(sort(string(fieldnames(values))), sort(expectedNames)), ...
        "SimuVerity:CandidateClosure:Formal90BundleValueContract", ...
        "The evaluator-owned current fixture row violates its public-name contract.");
else
    values = simuverity_xfluid04_public_nominal_inputs( ...
        benchmarkTaskId, publicNames);
end
end

function localRequireNames(actual, expected)
actual = sort(string(actual(:)));
expected = sort(string(expected(:)));
assert(isequal(actual, expected), ...
    "SimuVerity:CandidateClosure:Formal90PublicNominalInputContract", ...
    "Evaluator-owned current nominal input names do not match the public contract.");
end

function localRequirePresence(pathValue, expected, role)
assert(isfile(pathValue), ...
    "SimuVerity:CandidateClosure:Formal90RuntimeFileMissing", ...
    "The staged %s file is missing.", role);
actual = localFilePresence(pathValue);
assert(actual == lower(string(expected)), ...
    "SimuVerity:CandidateClosure:Formal90RuntimePresenceMismatch", ...
    "The staged %s file is not the registered artifact.", role);
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end
